package domain

import (
	"fmt"
	"regexp"
)

var actionIdentifier = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9_.-]*$`)

// ActionTaskPath is generated by the platform, never supplied by an owner.
func ActionTaskPath(action ActionDefinition) (string, error) {
	if action.Kind == ActionCheck {
		if !actionIdentifier.MatchString(action.ID) {
			return "", fmt.Errorf("%w: a check requires a safe immutable action ID", ErrInvalid)
		}
		return "tasks/checks/" + action.ID + ".yml", nil
	}
	switch action.Kind {
	case ActionInstall, ActionConfigure, ActionUpgrade, ActionRollback, ActionUninstall:
		return "tasks/" + string(action.Kind) + ".yml", nil
	default:
		return "", fmt.Errorf("%w: unsupported action kind %q", ErrInvalid, action.Kind)
	}
}

// ValidateActionBindings permits incomplete drafts, but never dangling or
// cross-release references. Complete contracts are required at execution and
// publication boundaries; a standalone check may be tested in an incomplete draft.
func ValidateActionBindings(release ComponentRelease, complete bool) error {
	byID := map[string]ActionDefinition{}
	kinds := map[ActionKind]bool{}
	for _, a := range release.Actions {
		if a.ID == "" || (a.ReleaseID != "" && a.ReleaseID != release.ID) {
			return fmt.Errorf("%w: action identity does not belong to this release", ErrInvalid)
		}
		if _, exists := byID[a.ID]; exists {
			return fmt.Errorf("%w: duplicate action ID %s", ErrInvalid, a.ID)
		}
		if a.Kind != ActionCheck && kinds[a.Kind] {
			return fmt.Errorf("%w: duplicate executable action kind %s", ErrInvalid, a.Kind)
		}
		byID[a.ID], kinds[a.Kind] = a, true
	}
	if complete && (!kinds[ActionInstall] || !kinds[ActionRollback]) {
		return fmt.Errorf("%w: install and rollback actions are required", ErrInvalid)
	}
	for _, a := range release.Actions {
		if a.Kind == ActionCheck {
			if a.PreCheckActionID != "" || a.PostCheckActionID != "" || a.Destructive {
				return fmt.Errorf("%w: check %s cannot bind checks or be destructive", ErrInvalid, a.ID)
			}
			continue
		}
		for _, binding := range []struct{ name, id string }{{"pre", a.PreCheckActionID}, {"post", a.PostCheckActionID}} {
			if binding.id == "" && !complete {
				continue
			}
			check, ok := byID[binding.id]
			if !ok || check.Kind != ActionCheck {
				return fmt.Errorf("%w: %s action %s requires a %s-check from the same release", ErrInvalid, a.Kind, a.ID, binding.name)
			}
		}
	}
	return nil
}

func (r ComponentRelease) ActionByID(id string) (ActionDefinition, bool) {
	for _, a := range r.Actions {
		if a.ID == id {
			return a, true
		}
	}
	return ActionDefinition{}, false
}
